using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.SceneManagement;
public sealed class CodeboundTitleScreen:MonoBehaviour {
 public CodeboundTitleSettings presentation;
 public Texture2D background,logo;public AudioClip music;public string gameScene="Assets/Scenes/SampleScene.unity";
 static bool requestedNew;static DungeonSaveData requestedSave;
 public static bool TakeNewGame(){bool value=requestedNew;requestedNew=false;return value;}
 public static DungeonSaveData TakeSavedGame(){var value=requestedSave;requestedSave=null;return value;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]static void ResetRequest(){requestedNew=false;requestedSave=null;}
 AudioClip appliedMusic;int page,selection;bool loading;string notice="";DungeonSaveData[] slots;string[] labels;
 void Awake(){var track=presentation!=null?presentation.music:music;if(track!=null)DungeonAudio.SetTitleTrack(track);appliedMusic=track;Time.timeScale=1;AudioListener.pause=false;AudioListener.volume=PlayerPrefs.GetFloat("Codebound.MasterVolume",1);}
 void OnDestroy(){DungeonAudio.SetTitleTrack(null);}
 public void NewGame(){if(loading)return;requestedSave=null;requestedNew=true;VirtualDungeon.GameStartContext.PrepareNewGame();Load();}
 public void ContinueSlot(int index){if(loading)return;try{string recovery;var value=DungeonSaveStore.Load(index,out recovery);if(value==null){notice="Slot vacio.";return;}requestedSave=value;requestedNew=false;DungeonSaveStore.ActiveSlot=index;VirtualDungeon.GameStartContext.PrepareSavedGame();Load();}catch(System.Exception e){notice="No se pudo cargar: "+e.Message;}}
 void Load(){loading=true;Time.timeScale=1;AudioListener.pause=false;SceneManager.LoadScene(gameScene,LoadSceneMode.Single);}
 public void OpenContinue(){page=1;selection=0;notice="";slots=new DungeonSaveData[DungeonSaveStore.SlotCount];labels=new string[slots.Length];for(int i=0;i<slots.Length;i++){try{slots[i]=DungeonSaveStore.Read(i);labels[i]=slots[i]!=null?DungeonPrototype.DescribeSaveSlot(slots[i]):"Vacio";}catch{labels[i]="No se puede leer";}}}
 public void OpenSettings(){page=2;selection=0;}
 void Choose(){if(page==0){if(selection==0)NewGame();else if(selection==1)OpenContinue();else OpenSettings();}else if(page==1){if(selection==DungeonSaveStore.SlotCount){page=0;selection=1;}else ContinueSlot(selection);}else if(selection==0){bool enabled=PlayerPrefs.GetInt(HelmetCRTController.PreferenceKey,1)!=0;PlayerPrefs.SetInt(HelmetCRTController.PreferenceKey,enabled?0:1);PlayerPrefs.Save();}else{page=0;selection=2;}}
 void Update(){if(loading||DungeonSaveRecoveryNotice.Active)return;var track=presentation!=null?presentation.music:music;if(track!=appliedMusic){DungeonAudio.SetTitleTrack(track);appliedMusic=track;}var k=Keyboard.current;var pad=Gamepad.current;bool back=k!=null&&k.escapeKey.wasPressedThisFrame||pad!=null&&pad.buttonEast.wasPressedThisFrame;if(back){page=0;selection=0;return;}int direction=k!=null&&k.downArrowKey.wasPressedThisFrame||pad!=null&&pad.dpad.down.wasPressedThisFrame?1:k!=null&&k.upArrowKey.wasPressedThisFrame||pad!=null&&pad.dpad.up.wasPressedThisFrame?-1:0;int count=page==0?3:page==1?DungeonSaveStore.SlotCount+1:2;if(direction!=0)selection=(selection+direction+count)%count;if(k!=null&&(k.enterKey.wasPressedThisFrame||k.spaceKey.wasPressedThisFrame)||pad!=null&&pad.buttonSouth.wasPressedThisFrame)Choose();}
 void OnGUI(){GUI.color=Color.white;float scale=Mathf.Min(Screen.width/1280f,Screen.height/720f);GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));float w=Screen.width/scale,h=Screen.height/scale;var art=presentation!=null?presentation.background:background;var mark=presentation!=null?presentation.logo:logo;if(art!=null)GUI.DrawTexture(new Rect(0,0,w,h),art,ScaleMode.ScaleAndCrop);else GUI.DrawTexture(new Rect(0,0,w,h),Texture2D.blackTexture);NeonDungeonUI.ApplyFont();NeonDungeonUI.FontSize=22;GUI.skin.button.fontSize=presentation!=null?presentation.fontSize:20;GUI.contentColor=presentation!=null?presentation.textColor:new Color(.65f,.85f,1);GUI.backgroundColor=presentation!=null?presentation.buttonColor:new Color(.12f,.05f,.3f);
  var logoArea=presentation!=null?presentation.logoRect:new Rect(.12f,.04f,.76f,.32f);if(mark!=null)GUI.DrawTexture(new Rect(w*logoArea.x,h*logoArea.y,w*logoArea.width,h*logoArea.height),mark,ScaleMode.ScaleToFit,true);
  if(page==0){float x=w/2-150,y=h-195;string[] options=presentation!=null?new[]{presentation.newGame,presentation.continueGame,presentation.settings}:new[]{"NUEVA PARTIDA","CONTINUAR","AJUSTES"};for(int i=0;i<3;i++)if(NeonDungeonUI.MenuAction(presentation!=null?presentation.ButtonRect(i,w,h):new Rect(x,y+i*52,300,42),options[i],selection==i)){selection=i;Choose();}}
  else if(page==1){float x=w/2-420,y=h*.32f;NeonDungeonUI.Panel(new Rect(x,y,840,430));NeonDungeonUI.Label(new Rect(x+25,y+15,790,35),"CONTINUAR",true);for(int i=0;i<DungeonSaveStore.SlotCount;i++){GUI.enabled=slots!=null&&slots[i]!=null;int slot=i;if(NeonDungeonUI.MenuAction(new Rect(x+25,y+60+i*42,790,36),"SLOT "+(i+1)+" - "+labels[i],selection==i))ContinueSlot(slot);}GUI.enabled=true;NeonDungeonUI.Label(new Rect(x+25,y+315,790,40),notice);if(NeonDungeonUI.MenuAction(new Rect(x+240,y+365,360,45),"VOLVER",selection==DungeonSaveStore.SlotCount)){page=0;selection=1;}}
  else{float x=w/2-260,y=h*.45f;NeonDungeonUI.Panel(new Rect(x,y,520,300));NeonDungeonUI.Label(new Rect(x+25,y+20,470,35),"AJUSTES",true);bool enabled=PlayerPrefs.GetInt(HelmetCRTController.PreferenceKey,1)!=0;bool chosen=GUI.Toggle(new Rect(x+40,y+85,440,40),enabled,"Pantalla CRT del casco");if(chosen!=enabled){PlayerPrefs.SetInt(HelmetCRTController.PreferenceKey,chosen?1:0);PlayerPrefs.Save();}NeonDungeonUI.Label(new Rect(x+40,y+135,440,30),"VOLUMEN");float volume=GUI.HorizontalSlider(new Rect(x+40,y+175,440,25),AudioListener.volume,0,1);if(!Mathf.Approximately(volume,AudioListener.volume)){AudioListener.volume=volume;PlayerPrefs.SetFloat("Codebound.MasterVolume",volume);PlayerPrefs.Save();}if(NeonDungeonUI.MenuAction(new Rect(x+100,y+225,320,45),"VOLVER",selection==1)){page=0;selection=2;}}
 }
}
